?><!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>WFCSystem — Painel administrativo</title>
<style>
:root{--navy:#101b33;--navy2:#182743;--blue:#2d6cdf;--bg:#f4f7fb;--ink:#172033;--muted:#69758a;--line:#e1e7f0;--white:#fff;--green:#1f9d68}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 Inter,Arial,sans-serif}button,input{font:inherit}.hidden{display:none!important}.login-shell{min-height:100vh;display:grid;place-items:center;padding:24px;background:linear-gradient(135deg,var(--navy),#263f72)}.login-card{width:min(430px,100%);padding:38px;background:#fff;border-radius:18px;box-shadow:0 22px 70px #07112666}.eyebrow{text-transform:uppercase;letter-spacing:.16em;font-size:11px;font-weight:800;color:var(--blue);margin:0 0 8px}.brand{margin:0;color:var(--navy);font-size:30px;letter-spacing:-.04em}.subtitle{color:var(--muted);margin:9px 0 28px}.field{display:grid;gap:7px;margin:16px 0}.field label{font-size:13px;font-weight:700}.field input{width:100%;padding:12px;border:1px solid var(--line);border-radius:9px;outline:0}.field input:focus{border-color:var(--blue);box-shadow:0 0 0 3px #2d6cdf22}.btn{border:0;border-radius:9px;padding:12px 16px;background:var(--blue);color:white;font-weight:700;cursor:pointer}.btn.full{width:100%;margin-top:10px}.btn.light{background:#fff;color:var(--navy);border:1px solid var(--line)}.error{color:#a12d42;background:#fff0f2;border-radius:8px;padding:10px 12px;font-size:13px}.app{min-height:100vh;display:grid;grid-template-columns:245px 1fr}.sidebar{background:var(--navy);color:#fff;padding:26px 18px}.side-brand{font-size:25px;font-weight:800;letter-spacing:-.04em}.side-caption{color:#a9bad8;font-size:12px;margin:2px 0 34px}.nav{display:grid;gap:7px}.nav button{border:0;background:transparent;color:#c5d0e3;text-align:left;border-radius:8px;padding:12px;cursor:pointer}.nav button.active,.nav button:hover{background:#ffffff16;color:#fff}.content{padding:34px;max-width:1250px;width:100%}.topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;margin-bottom:28px}.topbar h1{margin:0;font-size:34px;letter-spacing:-.04em}.topbar p{margin:5px 0 0;color:var(--muted)}.stats,.modules{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.stat,.module,.panel{background:#fff;border:1px solid var(--line);border-radius:14px;padding:20px}.stat small{color:var(--muted)}.stat strong{display:block;font-size:32px;color:var(--navy);margin-top:7px}.module{cursor:pointer;transition:.18s;border-top:4px solid var(--blue)}.module:hover{transform:translateY(-2px);box-shadow:0 10px 25px #17203312}.module h2{margin:0 0 7px;font-size:19px}.module p{margin:0;color:var(--muted)}.modules{grid-template-columns:repeat(4,1fr);margin-top:22px}.panel{margin-top:22px}.panel h2{margin:0 0 5px;font-size:19px}.status{color:var(--muted)}.badge{display:inline-block;color:var(--green);font-weight:700;font-size:12px;margin-top:8px}@media(max-width:850px){.app{display:block}.sidebar{padding:20px}.side-caption{margin-bottom:16px}.nav{display:flex;overflow:auto}.content{padding:22px}.modules{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.stats{grid-template-columns:1fr}.modules{grid-template-columns:1fr}.topbar{display:block}.topbar .btn{margin-top:14px}}
</style>
</head>
<body>
<div id="login" class="login-shell"><section class="login-card"><p class="eyebrow">WFCSystem · área restrita</p><h1 class="brand">Painel administrativo</h1><p class="subtitle">Cadastros e gestão da WFC Imóveis.</p><div id="loginError" class="error hidden"></div><form id="loginForm"><div class="field"><label for="identity">Usuário ou e-mail</label><input id="identity" autocomplete="username" required></div><div class="field"><label for="password">Senha</label><input id="password" type="password" autocomplete="current-password" required></div><button class="btn full" type="submit">Entrar no sistema</button></form></section></div>
<div id="app" class="app hidden"><aside class="sidebar"><div class="side-brand">WFCSystem</div><div class="side-caption">Sistema interno · versão 0.3</div><nav class="nav"><button class="active" data-module="Início">⌂ &nbsp; Início</button><button data-module="Imóveis">▣ &nbsp; Imóveis</button><button data-module="Clientes">♙ &nbsp; Clientes</button><button data-module="Prova Social">★ &nbsp; Prova Social</button><button data-module="Usuários">⚙ &nbsp; Usuários</button></nav></aside><main class="content"><header class="topbar"><div><p class="eyebrow">Painel interno</p><h1>Olá, <span id="userName">equipe</span>.</h1><p>Este é o sistema de gestão, separado do site público.</p></div><button id="logout" class="btn light">Sair</button></header><section class="stats"><article class="stat"><small>Imóveis cadastrados</small><strong id="properties">—</strong></article><article class="stat"><small>Clientes cadastrados</small><strong id="clients">—</strong></article><article class="stat"><small>Usuários da equipe</small><strong id="users">—</strong></article></section><section class="modules"><article class="module" data-module="Imóveis"><h2>Imóveis</h2><p>Cadastre e gerencie os imóveis da carteira.</p></article><article class="module" data-module="Clientes"><h2>Clientes</h2><p>Organize clientes e contatos da operação.</p></article><article class="module" data-module="Prova Social"><h2>Prova Social</h2><p>Gerencie depoimentos e resultados publicados.</p></article><article class="module" data-module="Usuários"><h2>Usuários</h2><p>Controle perfis e status da equipe.</p></article></section><section class="panel"><h2 id="panelTitle">Status do sistema</h2><p id="status" class="status">Consultando a API e o banco de dados…</p><span class="badge">● Ambiente administrativo online</span></section></main></div>
<script>
const api=(path,options={})=>fetch('api/v1/'+path,{credentials:'include',headers:{'Content-Type':'application/json',...(options.headers||{})},...options}).then(async r=>{const b=await r.json().catch(()=>({}));if(!r.ok)throw new Error(b.error||'Não foi possível concluir a operação.');return b});
const login=document.getElementById('login'),app=document.getElementById('app'),error=document.getElementById('loginError');
function showApp(me){login.classList.add('hidden');app.classList.remove('hidden');document.getElementById('userName').textContent=me.user.name||me.user.username;loadSummary()}
async function loadSummary(){try{const b=await api('dashboard/summary');document.getElementById('properties').textContent=b.data.properties;document.getElementById('clients').textContent=b.data.clients;document.getElementById('users').textContent=b.data.users;document.getElementById('status').textContent='Sessão ativa. Os números foram consultados no banco de dados.'}catch(e){document.getElementById('status').textContent=e.message}}
function selectModule(name){document.getElementById('panelTitle').textContent=name;document.getElementById('status').textContent='Módulo '+name+' selecionado. A tabela de gestão será aberta na próxima etapa.';document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.module===name))}
document.getElementById('loginForm').addEventListener('submit',async e=>{e.preventDefault();error.classList.add('hidden');const button=e.target.querySelector('button');button.disabled=true;button.textContent='Entrando…';try{showApp(await api('auth/login',{method:'POST',body:JSON.stringify({identity:document.getElementById('identity').value.trim(),password:document.getElementById('password').value})}))}catch(err){error.textContent=err.message;error.classList.remove('hidden')}finally{button.disabled=false;button.textContent='Entrar no sistema'}});
document.getElementById('logout').addEventListener('click',async()=>{await api('auth/logout',{method:'POST'}).catch(()=>{});app.classList.add('hidden');login.classList.remove('hidden')});document.querySelectorAll('[data-module]').forEach(el=>el.addEventListener('click',()=>selectModule(el.dataset.module)));api('auth/me').then(showApp).catch(()=>{});
</script>
</body></html>
